import{_ as t,a,b as s}from"./chunks/wireguardclustervpn.BFfLgpDv.js";import{_ as n,c as o,o as i,a2 as r}from"./chunks/framework.QTfwLiL8.js";const v=JSON.parse('{"title":"0014 Reversed Cluster Vpn","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0014-reversed-cluster-vpn","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0014-reversed-cluster-vpn/README.md","to":"README.md"},"title":"0014 Reversed Cluster Vpn","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0014-reversed-cluster-vpn/index.md","filePath":"docs/proposals/0014-reversed-cluster-vpn/index.md","lastUpdated":null}'),l={name:"docs/proposals/0014-reversed-cluster-vpn/index.md"};function p(d,e,c,h,u,g){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="gep-0014-reversed-cluster-vpn" tabindex="-1">GEP-0014: Reversed Cluster VPN <a class="header-anchor" href="#gep-0014-reversed-cluster-vpn" aria-label="Permalink to &quot;GEP-0014: Reversed Cluster VPN&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0014-reversed-cluster-vpn/readme/#Motivation">Motivation</a></li><li><a href="/docs/proposals/0014-reversed-cluster-vpn/readme/#Proposal">Proposal</a></li><li><a href="/docs/proposals/0014-reversed-cluster-vpn/readme/#Alternatives">Alternatives</a></li></ul><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>It is necessary to describe the current VPN solution and outline its shortcomings in order to motivate this proposal.</p><h3 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Today&#39;s Gardener cluster VPN solution has several issues including:</p><ol><li>Connection establishment is always from the seed cluster to the shoot cluster. This means that there needs to be connectivity both ways which is not desirable in many cases (OpenStack, VMware) and causes high effort in firewall configuration or extra infrastructure. These firewall configurations are prohibited in some cases due to security policies.</li><li>Shoot clusters must provide a VPN endpoint. This means extra cost for the endpoint (roughly €20/month on hyperscalers) or consumption of scarce resources (limited number of VMware NSX-T load balancers).</li></ol><p>A first implementation has been provided to resolve the issues with the <a href="https://github.com/gardener/enhancements/blob/main/geps/0014-reversed-cluster-vpn/11-apiserver-network-proxy.md" target="_blank" rel="noreferrer">Konnectivity server</a>. As we did find several shortcomings with the underlying technology component, the <a href="https://github.com/kubernetes-sigs/apiserver-network-proxy" target="_blank" rel="noreferrer">apiserver-network-proxy</a>, we believe that this is not a suitable way ahead. We have opened an <a href="https://github.com/kubernetes-sigs/apiserver-network-proxy/issues/180" target="_blank" rel="noreferrer">issue</a> and provided two solution proposals to the community. We do see some remedies, e.g., using the <a href="https://de.wikipedia.org/wiki/Quick_UDP_Internet_Connections" target="_blank" rel="noreferrer">Quick Protocol</a> instead of GRPC but we (a) consider the implementation effort significantly higher compared to this proposal and (b) would use an experimental protocol to solve a problem that can also be solved with existing and proven core network technologies.</p><p>We will therefore not continue to invest into this approach. We will, however, research a similar approach (see below, in <a href="/docs/proposals/0014-reversed-cluster-vpn/readme/#further-research">Further Research</a>).</p><h3 id="current-solution-outline" tabindex="-1">Current Solution Outline <a class="header-anchor" href="#current-solution-outline" aria-label="Permalink to &quot;Current Solution Outline&quot;">​</a></h3><p>The current solution consists of multiple VPN connections from each API server pod and the Prometheus pod of a control plane to an OpenVPN server running in the shoot cluster. This OpenVPN server is exposed via a load balancer that must have an IP address which is reachable from the seed cluster. The routing in the seed cluster pods is configured to route all traffic for the node, pod, and service ranges to the shoot cluster. This means that there is no address overlap allowed between seed- and shoot cluster node, pod, and service ranges.</p><p>In the seed cluster, the <code>vpn-seed</code> container is a sidecar to the kube-apiserver and prometheus pods. OpenVPN acts as a TCP client connecting to an OpenVPN TCP server. This is not optimal (e.g. tunneling TCP over TCP is discouraged) but at the time of development there was no UDP load balancer available on at least one of the major hyperscalers. Connectivity could have been switched to UDP later but the development effort was not spent.</p><p>The solution is depicted in this diagram:</p><p><img src="'+t+`" alt="alt text" title="Overview Current Cluster VPN"></p><p>These are the essential parts of the OpenVPN client configuration in the <code>vpn-seed</code> sidecar container:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># use TCP instead of UDP (commonly not supported by load balancers)</span></span>
<span class="line"><span>proto tcp-client</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># get all routing information from server</span></span>
<span class="line"><span>pull</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tls-client</span></span>
<span class="line"><span>key &quot;/srv/secrets/vpn-seed/tls.key&quot;</span></span>
<span class="line"><span>cert &quot;/srv/secrets/vpn-seed/tls.crt&quot;</span></span>
<span class="line"><span>ca &quot;/srv/secrets/vpn-seed/ca.crt&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tls-auth &quot;/srv/secrets/tlsauth/vpn.tlsauth&quot; 1</span></span>
<span class="line"><span>cipher AES-256-CBC</span></span>
<span class="line"><span></span></span>
<span class="line"><span># https://openvpn.net/index.php/open-source/documentation/howto.html#mitm</span></span>
<span class="line"><span>remote-cert-tls server</span></span>
<span class="line"><span></span></span>
<span class="line"><span># pull filter</span></span>
<span class="line"><span>pull-filter accept &quot;route 100.64.0.0 255.248.0.0&quot;</span></span>
<span class="line"><span>pull-filter accept &quot;route 100.96.0.0 255.224.0.0&quot;</span></span>
<span class="line"><span>pull-filter accept &quot;route 10.1.60.0 255.255.252.0&quot;</span></span>
<span class="line"><span>pull-filter accept &quot;route 192.168.123.&quot;</span></span>
<span class="line"><span>pull-filter ignore &quot;route&quot;</span></span>
<span class="line"><span>pull-filter ignore redirect-gateway</span></span>
<span class="line"><span>pull-filter ignore route-ipv6</span></span>
<span class="line"><span>pull-filter ignore redirect-gateway-ipv6</span></span></code></pre></div><p>Encryption is based on SSL certificates with an additional HMAC signature to all SSL/TLS handshake packets. As multiple clients connect to the OpenVPN server in the shoot cluster, all clients must be assigned a unique IP address. This is done by the OpenVPN server pushing that configuration to the client (keyword <code>pull</code>). As this is potentially problematic because the OpenVPN server runs in an untrusted environment, there are pull filters denying all but necessary routes for the pod, service, and node networks.</p><p>The OpenVPN server running in the shoot cluster is configured as follows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mode server</span></span>
<span class="line"><span>tls-server</span></span>
<span class="line"><span>proto tcp4-server</span></span>
<span class="line"><span>dev tun0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server 192.168.123.0 255.255.255.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>push &quot;route 10.243.0.0 255.255.128.0&quot;</span></span>
<span class="line"><span>push &quot;route 10.243.128.0 255.255.128.0&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>duplicate-cn</span></span>
<span class="line"><span></span></span>
<span class="line"><span>key &quot;/srv/secrets/vpn-shoot/tls.key&quot;</span></span>
<span class="line"><span>cert &quot;/srv/secrets/vpn-shoot/tls.crt&quot;</span></span>
<span class="line"><span>ca &quot;/srv/secrets/vpn-shoot/ca.crt&quot;</span></span>
<span class="line"><span>dh &quot;/srv/secrets/dh/dh2048.pem&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tls-auth &quot;/srv/secrets/tlsauth/vpn.tlsauth&quot; 0</span></span>
<span class="line"><span>push &quot;route 10.242.0.0 255.255.0.0&quot;</span></span></code></pre></div><p>It is a TCP TLS server and configured to automatically assign IP addresses for OpenVPN clients (<code>server</code> directive). In addition, it pushes the shoot cluster node-, pod-, and service ranges to the clients running in the seed cluster (<code>push</code> directive).</p><blockquote><p><strong>Note:</strong> The network mesh spanned by OpenVPN uses the network range <code>192.168.123.0 - 192.168.123.255</code>. This network range cannot be used in either shoot-, or seed clusters. If it is used, this might cause subtle problem due to network range overlaps. Unfortunately, this appears not to be well documented but this restriction exists since the very beginning. We should clean up this technical debt as part of the exercise.</p></blockquote><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>We intend to supersede the current VPN solution with the solution outlined in this proposal.</li><li>We intend to remove the code for the Konnectivity tunnel once this solution proposal has been validated.</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h3><ul><li>The solution is not a low latency or high throughput solution. As the kube-apiserver to shoot cluster traffic does not demand these properties, we do not intend to invest in improvements.</li><li>We do not intend to provide continuous availability to the shoot-seed VPN connection. We expect the availability to be comparable to the existing solution.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>The proposal is depicted in the following diagram:</p><p><img src="`+a+'" alt="alt text" title="Reversed Tunnel VPN"></p><p>We have added an OpenVPN server pod (<code>vpn-seed-server</code>) to each control plane. The OpenVPN client in the shoot cluster (<code>vpn-shoot-client</code>) connects to the OpenVPN server.</p><p>The two containers <code>vpn-seed-server</code> and <code>vpn-shoot-client</code> are new containers and are not related to containers in the <code>github.com/gardener/vpn</code> project. We will create a new project <code>github.com/gardener/vpn2</code> for these containers. With this solution we intend to supersede the containers from the <code>github.com/gardener/vpn</code> project.</p><p>A service <code>vpn-seed-server</code> of type <code>ClusterIP</code> is created for each control plane in its namespace.</p><p>The <code>vpn-shoot-client</code> pod connects to the correct <code>vpn-seed-server</code> service via the SNI passthrough proxy introduced with <a href="https://github.com/gardener/enhancements/blob/main/geps/0014-reversed-cluster-vpn/08-shoot-apiserver-via-sni.md" target="_blank" rel="noreferrer">SNI Passthrough proxy for kube-apiservers</a> on port 8132.</p><p>Shoot OpenVPN clients (<code>vpn-shoot-client</code>) connect to the correct OpenVPN Server using the http proxy feature provided by OpenVPN. A configuration is added to the envoy proxy to detect http proxy requests and open a connection attempt to the correct OpenVPN server.</p><p>The <code>kube-apiserver</code> to shoot cluster connections are established using the API server proxy feature via an envoy proxy sidecar container of the <code>vpn-seed-server</code> container.</p><p>The restriction regarding the <code>192.168.123.0/24</code> network range in the current VPN solution still applies to this proposal. No other restrictions are introduced. In the context of this GEP a pull request has been filed to block usage of that range by shoot clusters.</p><h3 id="performance-and-scalability" tabindex="-1">Performance and Scalability <a class="header-anchor" href="#performance-and-scalability" aria-label="Permalink to &quot;Performance and Scalability&quot;">​</a></h3><p>We do expect performance and throughput to be slightly lower compared to the existing solution. This is because the OpenVPN server acts as an additional hop and must decrypt and re-encrypt traffic that passes through. As there are no low latency or high throughput requirements for this connection, we do not assume this to be an issue.</p><h3 id="availability-and-failure-scenarios" tabindex="-1">Availability and Failure Scenarios <a class="header-anchor" href="#availability-and-failure-scenarios" aria-label="Permalink to &quot;Availability and Failure Scenarios&quot;">​</a></h3><p>This solution reuses multiple instances of the envoy component used for the kube-apiserver endpoints. We assume that the availability of kube-apiservers is good enough for the cluster VPN as well.</p><p>The OpenVPN client- and server pods are singleton pods in this approach and therefore are affected by potential failures and during cluster-, and control plane updates. Potential outages are only restricted to single shoot clusters and are comparable to the situation with the existing solution today.</p><h3 id="feature-gates-and-migration-strategy" tabindex="-1">Feature Gates and Migration Strategy <a class="header-anchor" href="#feature-gates-and-migration-strategy" aria-label="Permalink to &quot;Feature Gates and Migration Strategy&quot;">​</a></h3><p>We have introduced a gardenlet feature gate <code>ReversedVPN</code>. If <code>APIServerSNI</code> and <code>ReversedVPN</code> are enabled, the proposed solution is automatically enabled for all shoot clusters hosted by the seed. If <code>ReversedVPN</code> is enabled but <code>APIServerSNI</code> is not, the gardenlet will panic during startup as this is an invalid configuration. All existing shoot clusters will automatically be migrated during the next reconciliation. We assume that the <code>ReversedVPN</code> feature will work with Gardener as well as operator managed Istio.</p><p>We have also added a shoot annotation <code>alpha.featuregates.shoot.gardener.cloud/reversed-vpn</code>, which can override the feature gate to enable or disable the solution for individual clusters. This is only respected if <code>APIServerSNI</code> is enabled, otherwise it is ignored.</p><h3 id="security-review" tabindex="-1">Security Review <a class="header-anchor" href="#security-review" aria-label="Permalink to &quot;Security Review&quot;">​</a></h3><p>The change in the VPN solution will potentially open up new attack vectors. We will perform a thorough analysis outside of this document.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><h3 id="wireguard-and-kubelink-based-cluster-vpn" tabindex="-1">WireGuard and Kubelink based Cluster VPN <a class="header-anchor" href="#wireguard-and-kubelink-based-cluster-vpn" aria-label="Permalink to &quot;WireGuard and Kubelink based Cluster VPN&quot;">​</a></h3><p>We have done a detailed investigation and implementation of a reversed VPN based on WireGuard. While we believe that it is technically feasible and superior to the approach presented above, there are some concerns with regards to scalability, and high availability. As the WireGuard scenario based on kubelink is relevant for other use cases we continue to improve this implementation and address the concerns but we concede that this might not be on time for the cluster VPN. We nevertheless keep the implementation and provide an outline as part of this proposal.</p><p>The general idea of the proposal is to keep the existing cluster VPN solution more or less as is, but change the underlying network used for the <code>vpn seed =&gt; vpn shoot</code> connection. The underlying network should be established in the reversed direction, i.e., the shoot cluster should initiate the network connection, but it nevertheless should work in both directions.</p><p>We achieve this by tunneling the open vpn connection through a WireGuard tunnel, which is established from the shoot to the seed (note that WireGuard uses UDP as protocol). Independent of that we can also use UDP for the OpenVPN connection, but we can also stay with TCP as it was before. While this might look like a big change, it only introduces minor changes to the existing solution, but let&#39;s look at the details. In essence, the OpenVPN connection does not require a public endpoint in the shoot cluster but it uses the internal endpoint provided by the WireGuard tunnel.</p><p>This is roughly depicted in this diagram. Note that the <code>vpn-seed</code> and <code>vpn-shoot</code> containers only require very little changes and are fully backwards compatible.</p><p><img src="'+s+`" alt="alt text" title="Overview WireGuard Current Cluster VPN"></p><p>The WireGuard network needs a separate network range/CIDR. It has to be unique for the seed and all its shoot clusters. An example for an assumed workload of around 1000 shoot clusters would be <code>192.168.128.0/22</code> (1024 IP addresses), i.e. <code>192.168.128.0-192.168.131.255</code>. The IP addresses from this range need to be managed, but the IP address management (IPAM) using the Gardener Kubernetes objects like seed and shootstate as backing store is fairly straightforward. This is especially true as we do not expect large network ranges and only infrequent IP allocations. Hence, the IP address allocation can be quite simple, i.e., scan the range for a free IP address of all shoot clusters in a seed and allocate the first free address from the range.</p><p>There is another restriction: in case shoot clusters are configured to be seed clusters, this network range must not overlap with the &quot;parent&quot; seed cluster. If the parent seed cluster uses <code>192.168.128.0/22</code>, the child seed cluster can, for example, use <code>192.168.132.0/22</code>. Grandchildren can, however, use grandparent IP address ranges. Also, 2 children seed clusters can use identical ranges.</p><p>This slightly adds to the restrictions described in the current solution outline, in that the arbitrary chosen <code>192.168.123.0/24</code> range is restricted. For the purpose of this implementation, we propose to extend that restriction to <code>192.168.128.0/17</code> range. Most of it would be reserved for &quot;future use&quot;, however. We are well aware that this adds to the burden of correctly configuring Gardener landscapes.</p><p>We do consider this to be a challenge that needs to be addressed by careful configuration of the Gardener seed cluster infrastructure. Together with the <code>192.168.123.0/24</code> address range, these ranges should be automatically blocked for usage by shoots.</p><p>WireGuard can utilize the Linux kernel so that after initialization/configuration no user space processes are required. We propose to recommend the WireGuard kernel module as the default solution for all seeds. For shoot clusters, the WireGuard kernel based approach is also recommended, but the user space solution should also work, as we expect less traffic on the shoot side. We expect the userspace implementation to work on all operating systems supported by Gardener in case no kernel module is available.</p><p>Almost all seed clusters are already managed by Gardener and we assume that those are configured with the WireGuard kernel module. There are, however, some cases where we use other Kubernetes distributions as seed cluster which may not have an operating system with WireGuard module available. We will therefore generally support the user space WireGuard process on seed cluster but place a size restriction on the number of control planes on those seeds.</p><p>There is a user space implementation of WireGuard, which can be used on Linux distributions without the WireGuard kernel module. (WireGuard moved into the standard Linux kernel 5.6.) Our proposal can handle the kernel/user space switch transparently, i.e., we include the user space binaries and use them only when required. However, especially for the seed, the kernel based solution might be more attractive. Garden Linux 318.4.0 supports WireGuard.</p><p>We have looked at Ubuntu and SuSE chost:</p><ul><li>SuSE chost does not provide the WireGuard kernel module and it is not installable via zypper. It should, however, be straightforward for SuSE to include that in their next release.</li><li>Ubuntu does not provide the kernel module either but it can be installed using <code>apt-get install wireguard</code>. With that, it appears straightforward to provide an image with WireGuard pre-installed.</li></ul><p>On the seed, we add a WireGuard device to one node on the host network. For all other nodes on the seed, we adapt the routes accordingly to route traffic destined for the WireGuard network to our WireGuard node. The Kubernetes pods managing the WireGuard device and routes are only used for initial configuration and later reconfiguration. During runtime, they can restart without any impact on the operation of the WireGuard network as the WireGuard device is managed by the Linux kernel.</p><p>With Calico as the networking solution it is not easily possible to put the WireGuard endpoint into a pod. Putting the WireGuard endpoint into a pod would require to define it as a gateway in the api server or prometheus pods, but this is not possible since Calico does not span a proper subnet. While the defined CIDR in the pod network might be <code>100.96.0.0/11</code>, the network visible from within a pod is only <code>100.96.0.5/32</code>. This restriction might not exist with other networking solutions.</p><p>The WireGuard endpoint on the seed is exposed via a load balancer. We propose to use <a href="https://github.com/mandelsoft/kubelink" target="_blank" rel="noreferrer">kubelink</a> to manage the WireGuard configuration/device on the seed. We consider the management of the WireGuard endpoint to be complex especially in error situations which is the reason for utilizing kubelink as there is already significant experience managing an endpoint. We propose moving kubelink to the Gardener org in case it is used by this proposal.</p><p>Kubelink addresses three challenges managing WireGuard interfaces on cluster nodes. First, with WireGuard interfaces directly on the node (<code>hostNetwork=true</code>), the lifecycle of the interface is decoupled from the lifecycle of the pod that created it. This means that there will have to be means of cleaning up the interfaces and its configuration in case the interface moves to a different node. Second, additional routing information must be distributed across the cluster. The WireGuard CIDR is unknown to the network implementation, so additional routes must be distributed on all nodes of the cluster. Third, kubelink dynamically configures the Wireguard interface with endpoints and their public keys.</p><p>On the shoot, we create the keys and acquire the WireGuard IP in the standard secret generation. The data is added as a secret to the control plane and to the shootstate. The vpn shoot deployment is extended to include the WireGuard device setup inside the vpn shoot pod network. For certain infrastructures (AWS), we need a re-advertiser to resolve the seed WireGuard endpoint and evaluate whether the IP address changed.</p><p>While it is possible to configure a WireGuard device using DNS names, only IP addresses can be stored in Linux Kernel data structures. A change of a load balancer IP address can therefore not be mitigated on that level. As WireGuard dynamically adapts endpoint IP addresses, a change in load balancer IPs is mitigated in most but not all cases. This is why a re-advertiser is required for public cloud providers such as AWS.</p><p>The load balancer exposing the OpenVPN endpoint in the shoot cluster is no longer required and therefore removed if this functionality is used.</p><p>As we want to slowly expand the usage of the WireGuard solution, we propose to introduce a feature gate for it. Furthermore, since the WireGuard network requires a separate network range, we propose to introduce a new section to the seed settings with two additional flags (enabled &amp; cidr):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: core.gardener.cloud/v1beta1</span></span>
<span class="line"><span>kind: Seed</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: my-seed</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>  settings:</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>    wireguard:</span></span>
<span class="line"><span>      enabled: true</span></span>
<span class="line"><span>      cidr: 192.168.128.0/22</span></span></code></pre></div><p>Last but not least, we propose to introduce an annotation to the shoots to enable/disable the WireGuard tunnel explicitly.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: core.gardener.cloud/v1beta1</span></span>
<span class="line"><span>kind: Shoot</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: my-shoot</span></span>
<span class="line"><span>  annotations:</span></span>
<span class="line"><span>    alpha.featuregates.shoot.gardener.cloud/wireguard-tunnel: &quot;true&quot;</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p>Using this approach, it is easy to switch the solution on and off, i.e., migrate the shoot clusters automatically during ordinary reconciliation.</p><h4 id="high-availability" tabindex="-1">High Availability <a class="header-anchor" href="#high-availability" aria-label="Permalink to &quot;High Availability&quot;">​</a></h4><p>There is an issue if the node that hosts the WireGuard endpoint fails. The endpoint is migrated to another node, however, the time required to do this might exceed the budget for downtimes, although one could argue that a disruption of less than 30 seconds to 1 minute does not qualify as a downtime and will in almost all cases be not noticeable by end users.</p><p>In this case, we also assume that TCP connections won&#39;t be interrupted - they would just appear to hang. We will confirm this behavior and the potential downtime as part of the development and testing effort, as this is hard to predict.</p><p>As a possible mitigation, we propose to instantiate 2 Kubelink instances in the seed cluster that are served by two different load balancers. The instances must run on different nodes (if possible but we assume a proper seed cluster has more than one node). Each shoot cluster connects to both endpoints. This means that the OpenVPN server is reachable with two different IP addresses. The VPN seed sidecars must attempt to connect to both of them and will continue to do so. The &quot;Persistent Keepalive&quot; feature is set to 21 seconds by default but could be reduced. Due to the redundancy, however, this appears not to be necessary.</p><p>It is desirable that both connections are used in an equal manner. One strategy could be to use the kubelink 1 connection if the first target WireGuard address is even (the last byte of the IPv4 address), otherwise the kubelink 2 connection. The <code>vpn-seed</code> sidecars can then use the following configuration in their OpenVPN configuration file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;connection&gt;</span></span>
<span class="line"><span>remote 192.168.45.3 1194 udp</span></span>
<span class="line"><span>&lt;/connection&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;connection&gt;</span></span>
<span class="line"><span>remote 192.168.47.34 1194 udp</span></span>
<span class="line"><span>&lt;/connection&gt;</span></span></code></pre></div><p>OpenVPN will go through the list sequentially and try to connect to these endpoints.</p><p>As an additional mitigation, it appears possible to instantiate WireGuard devices on all hosts and replicate its relevant conntrack state across all cluster nodes. The relevant conntrack state keeps the state of all connections passing through the WireGuard interface (e.g. the WireGuard CIDR). conntrack and the tools to replicate conntrack state are part of the essential Linux netfilter tools package.</p><h4 id="load-considerations" tabindex="-1">Load Considerations <a class="header-anchor" href="#load-considerations" aria-label="Permalink to &quot;Load Considerations&quot;">​</a></h4><p>What happens in case of a failure? In this case, one router will end up owning all connections as the clients will attempt to use the next connection. This could be mitigated by adding a third redundant WireGuard connection. Using this strategy, the failure of one WireGuard endpoint would result in the equal distribution of connections to the two remaining interfaces. We believe, however, that this will not be necessary.</p><p>The cluster node running the Wireguard endpoint is essentially a router that routes all traffic to the various shoot clusters. This is established and proven technology that already exists since decades and has been highly optimized since then. This is also the technology that hyperscalers rely on to provide VPN connectivity to their customers. This said, hyperscalers essentially provide solutions based on IPsec, which is known not to scale as well as Wireguard. Wireguard is a relatively new technology but we have no doubt that it is less stable than existing IPsec solution.</p><p>Regarding performance, there is a lot of information on the Internet basically suggesting that Wireguard performs better than other VPN solutions such as IPsec or OpenVPN. One example is the <a href="https://www.wireguard.com/performance/" target="_blank" rel="noreferrer">Wireguard Performance Section</a> and the <a href="https://www.net.in.tum.de/fileadmin/bibtex/publications/papers/2020-ifip-moonwire.pdf" target="_blank" rel="noreferrer">Performance Analysis of VPN Gateways</a> document.</p><p>Based on this, we have no reason to believe that one router will not be able to handle all traffic going to and coming from shoot clusters. Nevertheless, we will closely monitor the situation in our tests and will take action if necessary.</p><h4 id="further-research" tabindex="-1">Further Research <a class="header-anchor" href="#further-research" aria-label="Permalink to &quot;Further Research&quot;">​</a></h4><p>Based on feedback on this proposal and while working on this implementation, we identified two additional approaches that we have not thought of so far. The first idea can be used to replace the &quot;inner&quot; OpenVPN implementation and the second can be used to replace WireGuard with OpenVPN and get rid of the single point of failure.</p><ol><li><p>Instead of using OpenVPN for the inner seed/shoot communication, we can use the proxy protocol and use a TCP proxy (e.g. envoy) in the shoot cluster to broker the seed-shoot connections. The advantage is that with this solution, seed- and shoot cluster network ranges are allowed to overlap. Disadvantages are increased implementation effort and less efficient network in terms of throughput and scalability. We believe, however, that the reduced network efficiency does not invalidate this option.</p></li><li><p>There is an option in OpenVPN to specify a tcp proxy as part of the endpoint configuration.</p></li></ol>`,90)]))}const m=n(l,[["render",p]]);export{v as __pageData,m as default};
